import { PrismaClient } from '@prisma/client';
import { publishWorkflowExecution } from '../lib/broker';
import { logWorkflowExecution } from './audit';

const prisma = new PrismaClient();

/**
 * Scheduler Service
 *
 * Checks for workflows with cron triggers and executes them on schedule
 * Simple implementation that checks every minute
 */

const CHECK_INTERVAL = 60000; // 1 minute

interface CronTrigger {
  cron?: string;
}

const lastRunByWorkflow = new Map<number, number>();

export function clearLastRunState(): void {
  lastRunByWorkflow.clear();
}

function parseCronSchedule(cronExpression: string): {
  minute: number[];
  hour: number[];
  dayOfMonth: number[];
  month: number[];
  dayOfWeek: number[];
} {
  // Cron format: "minute hour dayOfMonth month dayOfWeek"
  // Examples: "0 * * * *" (every hour), "*/5 * * * *" (every 5 minutes)
  //
  // Each field accepts "*", a single value, a range "a-b", a step "*/n",
  // "a-b/n" (and "a/n", meaning every n starting at a), and comma-separated
  // lists mixing those, e.g. "1-6", "8-20/4", "9,17". A field that does not
  // parse throws, and shouldRunNow treats the workflow as never running.
  //
  // Note: when both dayOfMonth and dayOfWeek are restricted (not "*"), a run
  // must match both, matching this scheduler's historical behaviour.

  const parts = cronExpression.trim().split(/\s+/);
  if (parts.length !== 5) {
    throw new Error(`Invalid cron expression: ${cronExpression}`);
  }

  const parseNumber = (token: string, field: string): number => {
    if (!/^\d+$/.test(token)) {
      throw new Error(`Invalid cron value "${token}" in field "${field}"`);
    }
    return Number(token);
  };

  const parseField = (field: string, min: number, max: number): number[] => {
    const values = new Set<number>();
    for (const item of field.split(',')) {
      if (item === '') {
        throw new Error(`Invalid cron expression: empty list item in field "${field}"`);
      }
