      let to: number;
      if (base === '*') {
        from = min;
        to = max;
      } else if (base.includes('-')) {
        const [a, b, ...rangeRest] = base.split('-');
        if (rangeRest.length > 0) {
          throw new Error(`Invalid cron field "${field}": range "${base}"`);
        }
        from = parseNumber(a, field);
        to = parseNumber(b, field);
      } else {
        from = parseNumber(base, field);
        to = stepText === undefined ? from : max;
      }
      const step = stepText === undefined ? 1 : parseNumber(stepText, field);
      if (step < 1 || from < min || to > max || from > to) {
        throw new Error(
          `Invalid cron field "${field}": "${item}" is outside ${min}-${max} or has an invalid step`
        );
      }
      for (let value = from; value <= to; value += step) {
        values.add(value);
      }
    }
    return [...values].sort((a, b) => a - b);
  };

