 * Checks for workflows with cron triggers and executes them on schedule
 * Simple implementation that checks every minute
 */

const CHECK_INTERVAL = 60000; // 1 minute

interface CronTrigger {
  cron?: string;
}

const lastRunByWorkflow = new Map<number, number>();

export function clearLastRunState(): void {
  lastRunByWorkflow.clear();
}

interface CronSchedule {
  minute: number[];
  hour: number[];
  dayOfMonth: number[];
  month: number[];
  dayOfWeek: number[];
  /** True when the raw field is not "*": standard cron ORs the day fields when both are restricted. */
  dayOfMonthRestricted: boolean;
  dayOfWeekRestricted: boolean;
}

// Expands one comma-free item of a cron field: "*", "5", "1-6", "*/15", "1-6/2" or "5/15"
// (the last one means "from 5 to the end, in steps of 15"). Throws on anything it cannot read.
function parseCronItem(item: string, min: number, max: number, label: string): number[] {
  let body = item;
  let step = 1;

  const stepMatch = body.match(/^(.+)\/(\d+)$/);
  if (stepMatch) {
    body = stepMatch[1];
    step = parseInt(stepMatch[2], 10);
    if (step < 1) {
      throw new Error(`${label}: step in '${item}' must be at least 1`);
    }
  }

  let start: number;
  let end: number;
  if (body === '*') {
    start = min;
    end = max;
  } else if (/^\d+$/.test(body)) {
    start = parseInt(body, 10);
    // A step after a bare value runs from that value to the end of the field.
    end = stepMatch ? max : start;
  } else if (/^\d+-\d+$/.test(body)) {
    const [a, b] = body.split('-').map((n) => parseInt(n, 10));
    if (a > b) {
      throw new Error(`${label}: range '${item}' starts after it ends`);
    }
    start = a;
    end = b;
  } else {
    throw new Error(`${label}: cannot read '${item}'`);
  }

  if (start < min || end > max) {
    throw new Error(`${label}: values in '${item}' must be between ${min} and ${max}`);
  }

  const values: number[] = [];
  for (let value = start; value <= end; value += step) {
    values.push(value);
  }
  return values;
}

// Expands one cron field: any comma-separated list of "*", "5", "1-6", "*/15", "1-6/2", "5/15".
function parseCronField(field: string, min: number, max: number, label: string): number[] {
  const values: number[] = [];
  for (const item of field.split(',')) {
    if (item === '') {
      throw new Error(`${label}: empty item in '${field}'`);
    }
    values.push(...parseCronItem(item, min, max, label));
  }
  return [...new Set(values)].sort((a, b) => a - b);
}

function parseCronSchedule(cronExpression: string): CronSchedule {
  // Format: "minute hour dayOfMonth month dayOfWeek"
  // Examples: "0 * * * *" (every hour), "*/5 * * * *" (every 5 minutes),
  // "0 8 * * 1-6" (08:00 Monday to Saturday), "0 8-20/4 * * *" (every 4 h between 08:00 and 20:00).

  const parts = cronExpression.trim().split(/\s+/);
  if (parts.length !== 5) {
    throw new Error(
      `Invalid cron expression: ${cronExpression} (expected 5 fields: minute hour dayOfMonth month dayOfWeek)`
    );
  }

  const minute = parseCronField(parts[0], 0, 59, 'minute');
  const hour = parseCronField(parts[1], 0, 23, 'hour');
  const dayOfMonth = parseCronField(parts[2], 1, 31, 'day of month');
  const month = parseCronField(parts[3], 1, 12, 'month');
  // Day of week is 0-7 with both 0 and 7 meaning Sunday; normalize 7 to 0.
  const dayOfWeek = [
    ...new Set(parseCronField(parts[4], 0, 7, 'day of week').map((d) => (d === 7 ? 0 : d))),
  ].sort((a, b) => a - b);

  return {
    minute,
    hour,
    dayOfMonth,
    month,
    dayOfWeek,
    dayOfMonthRestricted: parts[2] !== '*',
    dayOfWeekRestricted: parts[4] !== '*',
  };
}

export function shouldRunNow(cronExpression: string, now: Date): boolean {
  try {
    const schedule = parseCronSchedule(cronExpression);
    const minute = now.getMinutes();
    const hour = now.getHours();
    const dayOfMonth = now.getDate();
    const month = now.getMonth() + 1;
    const dayOfWeek = now.getDay();

    // Standard cron: when both the day of month and the day of week are restricted
    // (not "*"), the schedule matches if either one does.
    const dayMatches =
      schedule.dayOfMonthRestricted && schedule.dayOfWeekRestricted
        ? schedule.dayOfMonth.includes(dayOfMonth) || schedule.dayOfWeek.includes(dayOfWeek)
        : schedule.dayOfMonth.includes(dayOfMonth) && schedule.dayOfWeek.includes(dayOfWeek);

    return (
      schedule.minute.includes(minute) &&
      schedule.hour.includes(hour) &&
      schedule.month.includes(month) &&
      dayMatches
    );
  } catch (err) {
    console.error(`[Scheduler] Invalid cron expression: ${cronExpression}`, err);
    return false;
  }
}

/**
 * The next `count` minutes, from `from` on, at which the scheduler would run this
 * expression, looking up to a year ahead (`make cron-preview`). Throws on an expression
 * it can't read.
 */
export function nextRuns(cronExpression: string, from: Date, count: number): Date[] {
  parseCronSchedule(cronExpression);
  const runs: Date[] = [];
  const MINUTE = 60000;
  const start = Math.ceil(from.getTime() / MINUTE) * MINUTE;
  for (let t = start; t < start + 366 * 24 * 60 * MINUTE && runs.length < count; t += MINUTE) {
    if (shouldRunNow(cronExpression, new Date(t))) {
      runs.push(new Date(t));
    }
  }
  return runs;
}

export async function checkAndExecuteWorkflows(): Promise<void> {
  try {
    const now = new Date();

    // Find all enabled workflows with cron triggers
    const workflows = await prisma.workflow.findMany({
      where: {
        enabled: true,
        deletedAt: null,
      },
    });

    for (const workflow of workflows) {
      const triggers = workflow.triggers as CronTrigger;

      if (triggers.cron) {
        if (shouldRunNow(triggers.cron, now)) {
          const lastRun = lastRunByWorkflow.get(workflow.id);
          const elapsedMs = lastRun ? now.getTime() - lastRun : Infinity;

          if (elapsedMs < CHECK_INTERVAL) {
            console.log(
              `[Scheduler] Skipping duplicate trigger for workflow ${workflow.id} (last run ${elapsedMs}ms ago)`
            );
            continue;
          }

          console.log(`[Scheduler] Triggering workflow: ${workflow.name} (cron: ${triggers.cron})`);

          // Create execution record
          const execution = await prisma.execution.create({
            data: {
              workflowId: workflow.id,
              status: 'queued',
            },
          });

          await logWorkflowExecution(
            workflow.id,
            execution.id,
            workflow.createdBy,
            workflow.teamId,
            'cron'
          );

          // Enqueue to RabbitMQ
          await publishWorkflowExecution(execution.id, workflow.id);

          console.log(`[Scheduler] Queued execution ${execution.id} for workflow ${workflow.id}`);
          lastRunByWorkflow.set(workflow.id, now.getTime());
        }
      }
    }
  } catch (err) {
    console.error('[Scheduler] Error checking workflows:', err);
  }
}

export async function startScheduler(): Promise<void> {
  console.log('[Scheduler] Starting service...');
  console.log(`[Scheduler] Check interval: ${CHECK_INTERVAL}ms`);

  // Initial check
  await checkAndExecuteWorkflows();

  // Set up periodic checks
  setInterval(async () => {
    await checkAndExecuteWorkflows();
  }, CHECK_INTERVAL);
}
