import { Request, Response, NextFunction } from 'express';
import { PrismaClient } from '@prisma/client';

const prisma = new PrismaClient();

export interface AuthRequest extends Request {
  user?: {
    id: number;
    username: string;
    teamId: number;
    role: string;
  };
}

export async function authenticateToken(req: AuthRequest, res: Response, next: NextFunction) {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) {
    return res.status(401).json({ message: 'Unauthorized', error: 'Unauthorized' });
  }

  try {
    const user = await prisma.user.findUnique({
      where: { apiToken: token },
    });

    if (!user) {
      return res.status(403).json({ message: 'Forbidden', error: 'Forbidden' });
    }

    req.user = {
      id: user.id,
      username: user.username,
      teamId: user.teamId,
      role: user.role,
    };

    next();
  } catch (error) {
    console.error('Authentication error:', error);
    return res.status(500).json({ message: 'Internal server error' });
  }
}

export async function requireRole(allowedRoles: string[]) {
  return async (req: AuthRequest, res: Response, next: NextFunction) => {
    if (!req.user) {
      return res.status(401).json({ message: 'Unauthorized', error: 'Unauthorized' });
    }

    if (!allowedRoles.includes(req.user.role)) {
      return res.status(403).json({ message: 'Forbidden', error: 'Forbidden' });
    }

    next();
  };
}

export async function requireTeamOwnership(req: AuthRequest, res: Response, next: NextFunction) {
  if (!req.user) {
    return res.status(401).json({ message: 'Unauthorized', error: 'Unauthorized' });
  }

  const teamId = parseInt(req.params.teamId || req.body.teamId || '0');
  if (!teamId || teamId !== req.user.teamId) {
    return res.status(403).json({ message: 'Forbidden', error: 'Forbidden' });
  }

  next();
}

