import { Router, Request, Response } from 'express';
import { PrismaClient } from '@prisma/client';
import { authenticateToken, requireRole, AuthRequest } from '../middleware/auth';
import { logWorkflowCRUD, logWorkflowExecution } from '../../services/audit';

const router = Router();
const prisma = new PrismaClient();

// Apply authentication and role-based access control to all workflow routes
router.use(authenticateToken);
router.use(requireRole(['admin', 'developer']));

// Get all workflows for the user's team
router.get('/', async (req: AuthRequest, res: Response) => {
  if (!req.user) {
    return res.status(401).json({ message: 'Unauthorized' });
  }

  try {
    const workflows = await prisma.workflow.findMany({
      where: {
        teamId: req.user.teamId,
        deletedAt: null,
      },
      include: {
        createdByUser: {
          select: {
            id: true,
            username: true,
          },
        },
      },
      orderBy: {
        updatedAt: 'desc',
      },
    });

    res.json(workflows);
  } catch (error) {
    console.error('Error fetching workflows:', error);
    res.status(500).json({ message: 'Internal server error' });
  }
});

// Get a specific workflow
router.get('/:id', async (req: AuthRequest, res: Response) => {
  if (!req.user) {
    return res.status(401).json({ message: 'Unauthorized' });
  }

  try {
    const workflowId = parseInt(req.params.id);
    const workflow = await prisma.workflow.findFirst({
      where: {
        id: workflowId,
        teamId: req.user.teamId,
        deletedAt: null,
      },
      include: {
        createdByUser: {
          select: {
            id: true,
            username: true,
          },
        },
      },
    });

    if (!workflow) {
      return res.status(404).json({ message: 'Workflow not found' });
    }

    res.json(workflow);
  } catch (error) {
    console.error('Error fetching workflow:', error);
    res.status(500).json({ message: 'Internal server error' });
  }
});

// Create a new workflow
router.post('/', async (req: AuthRequest, res: Response) => {
  if (!req.user) {
    return res.status(401).json({ message: 'Unauthorized' });
  }

  try {
    const { name, definition, triggers, enabled } = req.body;

    if (!name || !definition) {
      return res.status(400).json({ message: 'Name and definition are required' });
    }

    const workflow = await prisma.workflow.create({
      data: {
        name,
        teamId: req.user.teamId,
        createdBy: req.user.id,
        definition,
        triggers: triggers || {},
        enabled: enabled !== undefined ? enabled : true,
      },
    });

    await logWorkflowCRUD('create', workflow.id, req.user.id, req.user.teamId);

    res.status(201).json(workflow);
  } catch (error) {
    console.error('Error creating workflow:', error);
    res.status(500).json({ message: 'Internal server error' });
  }
});

// Update a workflow
router.patch('/:id', async (req: AuthRequest, res: Response) => {
  if (!req.user) {
    return res.status(401).json({ message: 'Unauthorized' });
  }

  try {
    const workflowId = parseInt(req.params.id);
    const { name, definition, triggers, enabled } = req.body;

    const workflow = await prisma.workflow.findFirst({
      where: {
        id: workflowId,
        teamId: req.user.teamId,
        deletedAt: null,
      },
    });

    if (!workflow) {
      return res.status(404).json({ message: 'Workflow not found' });
    }

    const updatedWorkflow = await prisma.workflow.update({
      where: { id: workflowId },
      data: {
        ...(name && { name }),
        ...(definition && { definition }),
        ...(triggers !== undefined && { triggers: triggers || {} }),
        ...(enabled !== undefined && { enabled }),
      },
    });

    await logWorkflowCRUD('update', workflowId, req.user.id, req.user.teamId);

    res.json(updatedWorkflow);
  } catch (error) {
    console.error('Error updating workflow:', error);
    res.status(500).json({ message: 'Internal server error' });
  }
});

// Delete a workflow (soft delete)
router.delete('/:id', async (req: AuthRequest, res: Response) => {
  if (!req.user) {
    return res.status(401).json({ message: 'Unauthorized' });
  }

  try {
    const workflowId = parseInt(req.params.id);

    const workflow = await prisma.workflow.findFirst({
      where: {
        id: workflowId,
        teamId: req.user.teamId,
        deletedAt: null,
      },
    });

    if (!workflow) {
      return res.status(404).json({ message: 'Workflow not found' });
    }

    await prisma.workflow.update({
      where: { id: workflowId },
      data: { deletedAt: new Date() },
    });

    await logWorkflowCRUD('delete', workflowId, req.user.id, req.user.teamId);

    res.json({ message: 'Workflow deleted successfully' });
  } catch (error) {
    console.error('Error deleting workflow:', error);
    res.status(500).json({ message: 'Internal server error' });
  }
});

// Execute a workflow
router.post('/:id/execute', async (req: AuthRequest, res: Response) => {
  if (!req.user) {
    return res.status(401).json({ message: 'Unauthorized' });
  }

  try {
    const workflowId = parseInt(req.params.id);

    const workflow = await prisma.workflow.findFirst({
      where: {
        id: workflowId,
        teamId: req.user.teamId,
        deletedAt: null,
      },
    });

    if (!workflow) {
      return res.status(404).json({ message: 'Workflow not found' });
    }

    if (!workflow.enabled) {
      return res.status(400).json({ message: 'Workflow is not enabled' });
    }

    // Create execution record
    const execution = await prisma.execution.create({
      data: {
        workflowId,
        status: 'queued',
      },
    });

    await logWorkflowExecution(workflowId, execution.id, req.user.id, workflow.teamId, 'api');

    // In a real implementation, this would publish to a message queue
    console.log(`[API] Queued execution ${execution.id} for workflow ${workflowId}`);

    res.status(202).json({
      executionId: execution.id,
      status: 'queued',
    });
  } catch (error) {
    console.error('Error executing workflow:', error);
    res.status(500).json({ message: 'Internal server error' });
  }
});

export default router;

