```ts
function parseCronSchedule(cronExpression: string): {
  minute: number[];
  hour: number[];
  dayOfMonth: number[];
  month: number[];
  dayOfWeek: number[];
} {
  // 5-field cron: "minute hour dayOfMonth month dayOfWeek"
  // Each field is "*", "n", "a-b", "*/n" or "a-b/n" (and "n/m" = step from n to max).
  // Day of week: 0-6, 7 as an alias for 0 (Sunday).
  const parts = cronExpression.trim().split(/\s+/);
  if (parts.length !== 5) {
    throw new Error(`Invalid cron expression: ${cronExpression}`);
  }

  const parseField = (field: string, min: number, max: number, what: string): number[] => {
    const match = field.match(/^(\*|\d+|\d+-\d+)(?:\/(\d+))?$/);
    if (!match) {
      throw new Error(`Invalid cron field '${field}' for ${what}: use *, n, a-b, */n or a-b/n`);
    }
    const step = match[2] ? parseInt(match[2], 10) : 1;
    let start: number;
    let end: number;
    if (match[1] === '*') {
      start = min;
      end = max;
    } else if (match[1].includes('-')) {
      const [a, b] = match[1].split('-').map(n => parseInt(n, 10));
      if (a > b) {
        throw new Error(`Invalid cron range '${match[1]}' for ${what}: start above end`);
      }
      start = a;
      end = b;
    } else {
      start = parseInt(match[1], 10);
      end = match[2] ? max : start; // "n/m" steps from n to the end of the range
    }
    if (start < min || end > max) {
      throw new Error(`Cron field '${field}' for ${what} is out of range ${min}-${max}`);
    }
    const values: number[] = [];
    for (let v = start; v <= end; v += step) {
      values.push(v);
    }
    return values;
  };

  const dayOfWeek = parseField(parts[4], 0, 7, 'day of week').map(d => (d === 7 ? 0 : d));
  const unique = (values: number[]) => [...new Set(values)];

  return {
    minute: parseField(parts[0], 0, 59, 'minute'),
    hour: parseField(parts[1], 0, 23, 'hour'),
    dayOfMonth: parseField(parts[2], 1, 31, 'day of month'),
    month: parseField(parts[3], 1, 12, 'month'),
    dayOfWeek: unique(dayOfWeek),
  };
}
