  teamId: number;
  filename: string;
  content: any;
}

/**
 * Strip comments so files saved by lenient editors still import.
 *
 * Customers edit their workflow JSON in editors that accept comments (VS Code's
 * "JSON with comments" mode, `#` headers pasted from other formats, block comments).
 * JSON.parse is strict and rejects any of them, which made git sync silently skip the
 * file. We strip comment syntax before parsing:
 *   - a leading UTF-8 BOM (Windows editors often add one)
 *   - `#` line comments, `//` line comments and `/* ... */` block comments
 * The scanner is string-aware, so `#`, `//` and `/*` inside JSON strings (URLs,
 * message templates, ...) are left untouched.
 */
export function stripJsonComments(input: string): string {
  let out = '';
  let inString = false;
  let escaped = false;
  let i = 0;

  // Leading BOM, if any.
  if (input.charCodeAt(0) === 0xfeff) i = 1;

  while (i < input.length) {
    const c = input[i];

    if (inString) {
      out += c;
      if (escaped) {
        escaped = false;
      } else if (c === '\\') {
        escaped = true;
      } else if (c === '"') {
        inString = false;
      }
      i += 1;
      continue;
    }

    if (c === '"') {
      inString = true;
      out += c;
      i += 1;
      continue;
    }

    if (c === '#' || (c === '/' && input[i + 1] === '/')) {
      while (i < input.length && input[i] !== '\n') i += 1; // keep the newline
      continue;
    }

    if (c === '/' && input[i + 1] === '*') {
      const end = input.indexOf('*/', i + 2);
      i = end === -1 ? input.length : end + 2;
      continue;
    }

    out += c;
    i += 1;
  }

  return out;
}

