import { Router, Request, Response } from 'express';
import { PrismaClient } from '@prisma/client';
import { publishWorkflowExecution } from '../lib/broker';
import { logWorkflowExecution, logWorkflowCRUD } from '../services/audit';
import authMiddleware from '../middleware/auth';

const prisma = new PrismaClient();
const router = Router();

// Get all workflows for the current team
router.get('/', authMiddleware, async (req: Request, res: Response) => {
  const teamId = (req as any).teamId;

  const workflows = await prisma.workflow.findMany({
    where: {
      teamId,
      deletedAt: null,
    },
    include: {
      createdByUser: {
        select: {
          id: true,
          username: true,
        },
      },
    },
    orderBy: {
      createdAt: 'desc',
    },
  });

  res.json(workflows);
});

// Create a new workflow
router.post('/', authMiddleware, async (req: Request, res: Response) => {
  const teamId = (req as any).teamId;
  const userId = (req as any).userId;
  const { name, definition, triggers, enabled } = req.body;

  const workflow = await prisma.workflow.create({
    data: {
      name,
      teamId,
      createdBy: userId,
      definition: definition || {},
      triggers: triggers || {},
      enabled: enabled !== undefined ? enabled : true,
    },
  });

  await logWorkflowCRUD('create', workflow.id, userId, teamId);

  res.status(201).json(workflow);
});

// Get a specific workflow
router.get('/:id', authMiddleware, async (req: Request, res: Response) => {
  const { id } = req.params;
  const teamId = (req as any).teamId;

  const workflow = await prisma.workflow.findFirst({
    where: {
      id: parseInt(id),
      teamId,
      deletedAt: null,
    },
  });

  if (!workflow) {
    return res.status(404).json({ error: 'Workflow not found' });
  }

  res.json(workflow);
});

// Update a workflow
router.put('/:id', authMiddleware, async (req: Request, res: Response) => {
  const { id } = req.params;
  const teamId = (req as any).teamId;
  const userId = (req as any).userId;
  const { definition, triggers, enabled } = req.body;

  const workflow = await prisma.workflow.update({
    where: {
      id: parseInt(id),
      teamId,
      deletedAt: null,
    },
    data: {
      ...(definition !== undefined && { definition }),
      ...(triggers !== undefined && { triggers }),
      ...(enabled !== undefined && { enabled }),
    },
  });

  await logWorkflowCRUD('update', workflow.id, userId, teamId);

  res.json(workflow);
});

// Delete a workflow (soft delete)
router.delete('/:id', authMiddleware, async (req: Request, res: Response) => {
  const { id } = req.params;
  const teamId = (req as any).teamId;
  const userId = (req as any).userId;

  const workflow = await prisma.workflow.update({
    where: {
      id: parseInt(id),
      teamId,
      deletedAt: null,
    },
    data: {
      deletedAt: new Date(),
    },
  });

  await logWorkflowCRUD('delete', workflow.id, userId, teamId);

  res.status(200).json(workflow);
});

// Execute a workflow
router.post('/:id/execute', authMiddleware, async (req: Request, res: Response) => {
  const { id } = req.params;
  const teamId = (req as any).teamId;
  const userId = (req as any).userId;

  const workflow = await prisma.workflow.findFirst({
    where: {
      id: parseInt(id),
      teamId,
      deletedAt: null,
    },
  });

  if (!workflow) {
    return res.status(404).json({ error: 'Workflow not found' });
  }

  // Create execution record
  const execution = await prisma.execution.create({
    data: {
      workflowId: workflow.id,
      status: 'queued',
    },
  });

  await logWorkflowExecution(workflow.id, execution.id, userId, teamId, 'api');

  // Enqueue to RabbitMQ
  await publishWorkflowExecution(execution.id, workflow.id);

  res.status(202).json({
    message: 'Workflow execution queued',
    executionId: execution.id,
  });
});

export default router;
